from pathlib import Path
import json
from report_builder import F,add,render,R
# Clarify the narrower shipped contract; it does not promise other-drive LABEL.
F[14]['expected']='Honor a specified valid drive (original DOS LABEL drive syntax; tester DOS 3.3 expectation). InitechDOS Reference ch2-entries-b.tex:240-242 explicitly restricts LABEL to the current drive, so this is a compatibility gap, not a broken promise in that manual.'
add('TYPE cancellation','P2','Ctrl-C during TYPE prints non-file bytes and does not stop output',r'Run python3 evidence/resume_driver.py controlshort. It boots geometry-boot-fixture.img plus resume-fixture.img, CD \T, TYPE HUGE.TXT, then sends Ctrl-C after HUGE LINE 00005. The fixture has 2000 ASCII-only lines (88000 bytes).', 'The screen fills with non-text characters. The serial capture contains 14863 NUL bytes although the input contains none. Output then reaches HUGE LINE 01999 and the shell accepts ECHO AFTER-CANCEL. The original 10000-line repeat was stopped after 125 seconds, still printing at line 09233. Ctrl-S separately holds the serial byte count steady and resumes correctly.', 'Ctrl-C should stop TYPE and return a clean prompt; no bytes absent from the file should be printed (tester cancellation expectation and the brief; Initech Reference BREAK ch2-entries-a.tex:76 documents output-time break checking).', 'shots/resume-controlshort-ctrlc.png shots/resume-controlshort-returned.png evidence/resume-controlshort-serial.log evidence/resume-control-verification.json evidence/resume-fixtures/HUGE.TXT evidence/resume_driver.py evidence/advanced-control-serial.log')
add('XCOPY drives','P2','XCOPY writes to A: when D: is requested',r'Run resume_driver.py xcopy. From A:\T: XCOPY A:\T\ONE.TXT D:\DHOME\ /V; DIR D:\DHOME; DIR A:\DHOME; TYPE A:\DHOME\ONE.TXT; TYPE D:\DHOME\ONE.TXT. Stop QEMU and extract both volumes.', 'XCOPY reports 1 File(s) copied. D:\DHOME still contains only SAME.TXT. It instead creates A:\DHOME\ONE.TXT containing 41 4c 50 48 41 0d 0a (ALPHA plus CR/LF). A source qualified with D: also yields zero copies. The stopped-image mcopy return codes are 0 for the A: file and 1 (not found) for the D: file.', 'Resolve source and destination drive letters independently and write only to the requested destination (DOS XCOPY; InitechDOS Reference ch2-entries-c.tex:216-229 accepts drive-qualified source and target).', 'shots/resume-xcopy-location.png shots/resume-xcopy-wrong-volume.png evidence/resume-xcopy-serial.log evidence/resume-xcopy-verification.json evidence/resume-xcopy-A-ONE.TXT evidence/resume-xcopy-D-listing.txt evidence/resume_driver.py')
add('Batch chaining','P2','Invoking a batch without CALL returns to the caller anyway',r'Run resume_driver.py batch. From A:\T run CHAIN.BAT; it prints BEFORE, invokes \CASES\CHILD.BAT arg without CALL, then has ECHO SHOULD-NOT-RETURN.', 'CHILD=arg is followed by SHOULD-NOT-RETURN. The older followup run likewise prints CHAIN-AFTER.', 'A plain batch invocation transfers control; only CALL resumes the caller (DOS Reference CALL p.142/PDF227).', 'shots/resume-batch-flow.png evidence/resume-batch-serial.log evidence/resume-fixtures/CHAIN.BAT evidence/cases/CHILD.BAT evidence/manual-page-227.txt')
add('Batch cancellation','P2','Ctrl-C ends a batch without the DOS termination question',r'Run resume_driver.py batch; \CASES\BREAK.BAT waits at PAUSE. Press Ctrl-C. Repeat with LOOP.BAT, which repeatedly uses ECHO and GOTO.', 'Both immediately return to the DOS prompt after ^C. There is no Terminate batch job (Y/N)? and no option to continue. The PAUSE remainder is not executed.', 'Ask Terminate batch job (Y/N)? and allow N to continue (DOS Reference p.149/PDF234). InitechDOS Reference ch4-batch.tex:38-39 documents immediate cancellation, so this is an explicit compatibility gap.', 'shots/resume-batch-pause-break.png shots/resume-batch-loop-break.png evidence/resume-batch-serial.log evidence/cases/BREAK.BAT evidence/resume-fixtures/LOOP.BAT evidence/resume-manual-page-234.txt')
add('DEL directory operand','P2','DEL directory refuses the documented delete-all-files form',r'Boot suite2; run \CASES\B023.BAT: MD DELDIR; COPY ONE.TXT DELDIR\ONE.TXT; DEL DELDIR; DIR DELDIR.', 'DEL reports Access denied; ONE.TXT remains in the directory.', 'Treat the directory name as its contained files and apply the delete-all confirmation, leaving the directory itself (DOS Reference p.56/PDF141 explicitly says to give a directory name to delete its files).', 'shots/suite2-B023-del-directory.png evidence/suite2-B023.txt evidence/extracted/suite2/T/DELDIR/ONE.TXT evidence/manual-page-141.txt')
add('DATE','P2','DATE without an argument does not offer date entry',r'Boot suite3; run \CASES\B038.BAT or type DATE.', 'Only Current date is ... is displayed; execution proceeds to the next command. Startup without AUTOEXEC does have the date question.', 'Offer Enter new date (mm-dd-yy): and let Enter retain it (DOS Reference p.55/PDF140). The Initech manual describes its display-only behavior, so this is compatibility.', 'shots/suite3-B038-date-formats.png evidence/suite3-B038.txt evidence/manual-page-140.txt')
add('TIME','P2','TIME without an argument does not offer time entry',r'Boot suite3; run \CASES\B039.BAT or type TIME.', 'Only Current time is ... is displayed; the shell continues without an entry question. Startup without AUTOEXEC does have a time prompt.', 'Prompt for a new time when no argument is supplied (DOS Reference p.121/PDF206). The Initech manual describes display-only TIME; this is compatibility.', 'shots/suite3-B039-time-values.png evidence/suite3-B039.txt evidence/manual-page-206.txt')
